const sessionStore = require("./session-store"); // In-memory store module passed in via router-level dependency injection

const router = express.Router();
router.use(express.json());

router.get("/sessions", (req, res) => {
  const { level, paid } = req.query;
  const sessions = sessionStore.getSessions();
  const total = sessions.length;

  res.json({ sessions, total });
});

router.post("/sessions", (req, res) => {
  const { plate, level } = req.body;
  const sessions = sessionStore.getSessions();
  const total = sessions.length;

  if (plate === "") {
    return res.status(400).json({ code: "INVALID_PLATE" });
  }

  if (level < 0 || level > 5) {
    return res.status(400).json({ code: "INVALID_LEVEL" });
  }

  if (sessions.some(session => session.plate === plate)) {
    return res.status(409).json({ code: "SESSION_EXISTS" });
  }

  const session = {
    plate,
    level,
    paid: paid === "true",
  };

  sessionStore.addSession(session);
  res.status(201).json(session);
});

router.patch("/sessions/:id/pay", (req, res) => {
  const { id } = req.params;
  const session = sessionStore.getSession(id);
  const total = sessionStore.getSessions().length;

  if (session.paid) {
    return res.status(400).json({ code: "SESSION_ALREADY_PAID" });
  }

  session.paid = true;
  sessionStore.updateSession(session);
  res.status(200).json(session);
});

router.delete("/sessions/:id", (req, res) => {
  const { id } = req.params;
  const session = sessionStore.getSession(id);
  const total = sessionStore.getSessions().length;

  if (!session) {
    return res.status(404).json({ code: "SESSION_NOT_FOUND" });
  }

  sessionStore.deleteSession(id);
  res.status(200).json(session);
});
